/// <reference types="vite/client" />
// Cape textures and the Cosmetics page's 3D preview.
//
// The textures in assets/capes/ are generated by scripts/generate-capes.mjs in
// Minecraft's cape layout (2× resolution), so the Fabric mod can ship the
// same files. Animated capes stack their frames vertically; capes.json holds
// each one's frame count and frame time in game ticks (50 ms).
//
// The preview is a plain gray player with dark gray outlines, seen from the
// side and walking, so the cape is the only thing with colour on screen.

type ThreeModule = typeof import('three');

const textureUrls = import.meta.glob('./assets/capes/*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>;
const capeMeta = (Object.values(import.meta.glob('./assets/capes/capes.json', { eager: true, import: 'default' }))[0] ?? {}) as
  Record<string, { frames: number; frametime: number; width: number; height: number }>;

const TICK_MS = 50;
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

export interface CapeSheet { id: string; img: HTMLImageElement; frames: number; frametime: number; width: number; height: number }

const sheets = new Map<string, Promise<CapeSheet | null>>();
export function loadCape(id: string): Promise<CapeSheet | null> {
  let p = sheets.get(id);
  if (!p) {
    const url = textureUrls[`./assets/capes/${id}.png`];
    const meta = capeMeta[id];
    p = !url || !meta ? Promise.resolve(null) : new Promise(resolve => {
      const img = new Image();
      img.onload = () => resolve({ id, img, ...meta });
      img.onerror = () => resolve(null);
      img.src = url;
    });
    sheets.set(id, p);
  }
  return p;
}

export function frameAt(sheet: CapeSheet, ms: number): number {
  return sheet.frames > 1 ? Math.floor(ms / (sheet.frametime * TICK_MS)) % sheet.frames : 0;
}

// Draws the outside of the cape (the part you see from behind), pixel-sharp,
// centred in the canvas.
export function drawCapeFront(ctx: CanvasRenderingContext2D, sheet: CapeSheet, frame: number) {
  const { width: cw, height: ch } = ctx.canvas;
  const sx = 2, sy = 2 + frame * sheet.height, sw = 20, sh = 32;
  const scale = Math.floor(Math.min(cw / sw, ch / sh));
  const w = sw * scale, h = sh * scale;
  ctx.clearRect(0, 0, cw, ch);
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(sheet.img, sx, sy, sw, sh, Math.round((cw - w) / 2), Math.round((ch - h) / 2), w, h);
}

// ── 3D preview ────────────────────────────────────────────────────────────────
export interface CapeViewer { setCape(id: string | null): void; dispose(): void }

export async function createCapeViewer(host: HTMLElement): Promise<CapeViewer> {
  const THREE: ThreeModule = await import('three');

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  host.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(26, 1, 1, 400);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x3a3a40, 2.1));
  const sun = new THREE.DirectionalLight(0xffffff, 2.2);
  sun.position.set(30, 50, 40);
  scene.add(sun);

  // Units are Minecraft model pixels; the player stands on y = 0 facing +z.
  const skin = new THREE.MeshLambertMaterial({ color: 0x8a8a8a, polygonOffset: true, polygonOffsetFactor: 2, polygonOffsetUnits: 2 });
  const outline = new THREE.LineBasicMaterial({ color: 0x232323 });
  function part(w: number, h: number, d: number, offset: [number, number, number], parent: import('three').Object3D) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const mesh = new THREE.Mesh(geo, skin);
    mesh.position.set(...offset);
    mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo), outline));
    parent.add(mesh);
    return mesh;
  }
  function pivot(x: number, y: number, z: number, parent: import('three').Object3D) {
    const g = new THREE.Group();
    g.position.set(x, y, z);
    parent.add(g);
    return g;
  }

  const player = new THREE.Group();
  scene.add(player);
  part(8, 12, 4, [0, 18, 0], player);                                  // body
  const head = pivot(0, 24, 0, player);  part(8, 8, 8, [0, 4, 0], head);
  const armR = pivot(-6, 22, 0, player); part(4, 12, 4, [0, -4, 0], armR);
  const armL = pivot(6, 22, 0, player);  part(4, 12, 4, [0, -4, 0], armL);
  const legR = pivot(-2, 12, 0, player); part(4, 12, 4, [0, -6, 0], legR);
  const legL = pivot(2, 12, 0, player);  part(4, 12, 4, [0, -6, 0], legL);

  // Cape: a 10×16×1 box hanging from the top of the back, UV-mapped to the
  // standard cape regions (in 64×32 texture units).
  const capePivot = pivot(0, 24, -2, player);
  const capeGeo = new THREE.BoxGeometry(10, 16, 1);
  {
    // BoxGeometry face order: +x, -x, +y, -y, +z, -z; four UVs per face.
    const regions: Array<[number, number, number, number]> = [
      [0, 1, 1, 16],   // +x side
      [11, 1, 1, 16],  // -x side
      [1, 0, 10, 1],   // top
      [11, 0, 10, 1],  // bottom
      [12, 1, 10, 16], // +z: lining, against the player's back
      [1, 1, 10, 16],  // -z: the outside, seen from behind
    ];
    const uv = capeGeo.attributes.uv as import('three').BufferAttribute;
    regions.forEach(([x, y, w, h], face) => {
      const u0 = x / 64, u1 = (x + w) / 64, v0 = 1 - y / 32, v1 = 1 - (y + h) / 32;
      const i = face * 4;
      uv.setXY(i, u0, v0); uv.setXY(i + 1, u1, v0); uv.setXY(i + 2, u0, v1); uv.setXY(i + 3, u1, v1);
    });
    uv.needsUpdate = true;
  }
  const capeCanvas = document.createElement('canvas');
  const capeCtx = capeCanvas.getContext('2d')!;
  const capeTex = new THREE.CanvasTexture(capeCanvas);
  capeTex.magFilter = THREE.NearestFilter;
  capeTex.minFilter = THREE.NearestFilter;
  capeTex.generateMipmaps = false;
  capeTex.colorSpace = THREE.SRGBColorSpace;
  const capeMat = new THREE.MeshLambertMaterial({ map: capeTex });
  const cape = new THREE.Mesh(capeGeo, capeMat);
  cape.position.set(0, -8, -0.5);
  capePivot.add(cape);
  capePivot.visible = false;

  // Soft shadow under the feet keeps the figure grounded.
  const shadowCanvas = document.createElement('canvas');
  shadowCanvas.width = shadowCanvas.height = 64;
  const sctx = shadowCanvas.getContext('2d')!;
  const grad = sctx.createRadialGradient(32, 32, 2, 32, 32, 32);
  grad.addColorStop(0, 'rgba(0,0,0,0.55)');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  sctx.fillStyle = grad;
  sctx.fillRect(0, 0, 64, 64);
  const shadow = new THREE.Mesh(
    new THREE.PlaneGeometry(22, 14),
    new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(shadowCanvas), transparent: true, depthWrite: false }),
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.05;
  scene.add(shadow);

  // Camera: from the side and a little behind, so the cape faces you as it
  // swings. Drag sideways to walk around the player.
  const target = new THREE.Vector3(0, 15, 0);
  let yaw = THREE.MathUtils.degToRad(118);
  const distance = 92, height = 21;
  function placeCamera() {
    camera.position.set(Math.sin(yaw) * distance, height, Math.cos(yaw) * distance);
    camera.lookAt(target);
  }
  placeCamera();

  let dragX: number | null = null;
  const onDown = (e: PointerEvent) => { dragX = e.clientX; renderer.domElement.setPointerCapture(e.pointerId); };
  const onMove = (e: PointerEvent) => {
    if (dragX === null) return;
    yaw -= (e.clientX - dragX) * 0.012;
    dragX = e.clientX;
    placeCamera();
  };
  const onUp = () => { dragX = null; };
  renderer.domElement.addEventListener('pointerdown', onDown);
  renderer.domElement.addEventListener('pointermove', onMove);
  renderer.domElement.addEventListener('pointerup', onUp);
  renderer.domElement.addEventListener('pointercancel', onUp);

  function resize() {
    const w = host.clientWidth, h = host.clientHeight;
    if (!w || !h) return;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  const ro = new ResizeObserver(resize);
  ro.observe(host);
  resize();

  let sheet: CapeSheet | null = null;
  let shownFrame = -1;
  let wantedId: string | null = null;
  function setCape(id: string | null) {
    wantedId = id;
    if (!id) { sheet = null; capePivot.visible = false; return; }
    loadCape(id).then(s => {
      if (wantedId !== id) return;
      sheet = s;
      shownFrame = -1;
      if (!s) { capePivot.visible = false; return; }
      capeCanvas.width = s.width;
      capeCanvas.height = s.height;
      capePivot.visible = true;
    });
  }

  // Walk cycle: legs and arms swing opposite each other, the body bobs on
  // each step, and the cape lifts and flutters with the stride.
  const start = performance.now();
  let raf = 0;
  function frame(now: number) {
    raf = requestAnimationFrame(frame);
    if (document.hidden || !host.isConnected || host.offsetWidth === 0) return;
    const t = (now - start) / 1000;
    const phase = reduceMotion ? Math.PI / 2 : t * Math.PI * 2 * 0.95;
    const swing = Math.sin(phase);
    legR.rotation.x = swing * 0.6;
    legL.rotation.x = -swing * 0.6;
    armR.rotation.x = -swing * 0.5;
    armL.rotation.x = swing * 0.5;
    armR.rotation.z = -0.04;
    armL.rotation.z = 0.04;
    player.position.y = reduceMotion ? 0 : Math.abs(Math.cos(phase)) * 0.55;
    head.rotation.x = reduceMotion ? 0 : Math.sin(phase * 2) * 0.025;
    capePivot.rotation.x = 0.3 + Math.abs(swing) * 0.08 + (reduceMotion ? 0 : Math.sin(phase * 2 + 0.9) * 0.05);
    capePivot.rotation.z = reduceMotion ? 0 : Math.sin(phase) * 0.02;

    if (sheet) {
      const f = frameAt(sheet, now);
      if (f !== shownFrame) {
        shownFrame = f;
        capeCtx.clearRect(0, 0, sheet.width, sheet.height);
        capeCtx.drawImage(sheet.img, 0, f * sheet.height, sheet.width, sheet.height, 0, 0, sheet.width, sheet.height);
        capeTex.needsUpdate = true;
      }
    }
    renderer.render(scene, camera);
  }
  raf = requestAnimationFrame(frame);

  return {
    setCape,
    dispose() {
      cancelAnimationFrame(raf);
      ro.disconnect();
      renderer.dispose();
      renderer.domElement.remove();
    },
  };
}
